/*
  Seed ngữ pháp Minna no Nihongo N5 từ tài liệu người dùng cung cấp:
  "List ngữ pháp N5.pdf".

  Kết quả: 1 khóa học, 25 section (Bài 1-25), 94 grammar content.
  Chạy database_language_center_mysql.sql trước file này.
  Có thể chạy lại file mà không tạo dữ liệu trùng.
*/

USE LanguageCenterDB;

START TRANSACTION;

-- Remove only the synthetic 50-lesson dataset generated by the previous seed.
DELETE content
FROM course_content content
JOIN course_section section ON section.id = content.section_id
JOIN course old_course ON old_course.id = section.course_id
WHERE old_course.course_code = 'JA-MINNA-50';

DELETE section
FROM course_section section
JOIN course old_course ON old_course.id = section.course_id
WHERE old_course.course_code = 'JA-MINNA-50';

DELETE FROM course WHERE course_code = 'JA-MINNA-50';

SELECT lv.id INTO @minna_n5_level_id
FROM level lv
JOIN language lg ON lg.id = lv.language_id
WHERE lg.language_code = 'JA' AND lv.level_code = 'N5'
LIMIT 1;

INSERT INTO course (
    level_id, course_code, course_name, slug, short_description, description,
    target_audience, prerequisites, learning_outcomes, syllabus_summary,
    tuition_fee, total_sessions, duration_hours, status, publication_status,
    published_at, is_featured, created_at, updated_at
)
SELECT
    @minna_n5_level_id,
    'JA-MINNA-N5-GRAMMAR',
    'Ngữ pháp Minna no Nihongo N5',
    'ngu-phap-minna-no-nihongo-n5',
    'Tổng hợp 94 điểm ngữ pháp N5 theo 25 bài Minna no Nihongo.',
    'Khóa tham khảo ngữ pháp sơ cấp, mỗi nội dung gồm công thức, nghĩa và ví dụ.',
    'Người mới học tiếng Nhật hoặc đang ôn JLPT N5.',
    'Nên biết Hiragana và Katakana cơ bản.',
    'Nắm được các mẫu câu và cấu trúc ngữ pháp trọng tâm ở trình độ N5.',
    '25 bài với 94 điểm ngữ pháp được tải theo từng section.',
    0, 25, 50, 'ACTIVE', 'PUBLISHED', NOW(), TRUE, NOW(), NOW()
WHERE @minna_n5_level_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1 FROM course WHERE course_code = 'JA-MINNA-N5-GRAMMAR'
  );

SELECT id INTO @minna_n5_course_id
FROM course
WHERE course_code = 'JA-MINNA-N5-GRAMMAR'
LIMIT 1;

INSERT INTO course_section (course_id, title, description, display_order)
WITH RECURSIVE lesson_numbers AS (
    SELECT 1 AS lesson_number
    UNION ALL
    SELECT lesson_number + 1 FROM lesson_numbers WHERE lesson_number < 25
)
SELECT
    @minna_n5_course_id,
    CONCAT('Bài ', lesson_number),
    CONCAT('Các điểm ngữ pháp N5 thuộc bài ', lesson_number, '.'),
    lesson_number
FROM lesson_numbers
WHERE @minna_n5_course_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1
      FROM course_section existing_section
      WHERE existing_section.course_id = @minna_n5_course_id
        AND existing_section.display_order = lesson_numbers.lesson_number
  );

DROP TEMPORARY TABLE IF EXISTS minna_n5_grammar_seed;

CREATE TEMPORARY TABLE minna_n5_grammar_seed (
    lesson_number      INT NOT NULL,
    item_order         INT NOT NULL,
    grammar_pattern    VARCHAR(500) NOT NULL,
    meaning_text       TEXT NOT NULL,
    example_text       TEXT NULL,
    PRIMARY KEY (lesson_number, item_order)
);

