INSERT INTO course_content (
    section_id, title, summary, content_html, content_type,
    display_order, is_preview, publication_status
)
SELECT
    section.id,
    grammar.grammar_pattern,
    grammar.meaning_text,
    CONCAT(
        '<p><strong>Công thức:</strong> ', grammar.grammar_pattern, '</p>',
        '<p><strong>Ý nghĩa:</strong> ', grammar.meaning_text, '</p>',
        CASE
            WHEN grammar.example_text IS NULL THEN ''
            ELSE CONCAT('<p><strong>Ví dụ:</strong> ', grammar.example_text, '</p>')
        END
    ),
    'GRAMMAR',
    grammar.item_order,
    TRUE,
    'PUBLISHED'
FROM minna_n5_grammar_seed grammar
JOIN course_section section
  ON section.course_id = @minna_n5_course_id
 AND section.display_order = grammar.lesson_number
WHERE NOT EXISTS (
    SELECT 1
    FROM course_content existing_content
    WHERE existing_content.section_id = section.id
      AND existing_content.display_order = grammar.item_order
);

DROP TEMPORARY TABLE minna_n5_grammar_seed;

COMMIT;

SELECT
    course.id,
    course.course_code,
    COUNT(DISTINCT section.id) AS section_count,
    COUNT(content.id) AS content_count
FROM course
LEFT JOIN course_section section ON section.course_id = course.id
LEFT JOIN course_content content ON content.section_id = section.id
WHERE course.course_code = 'JA-MINNA-N5-GRAMMAR'
GROUP BY course.id, course.course_code;
